/**
 * App Utilities
 *
 * Helper functions for project creation and management.
 */
import { ADJECTIVES, NOUNS } from "./data/slug-words.js";
export function generateRandomSlug() {
    const adj = ADJECTIVES[Math.floor(Math.random() * ADJECTIVES.length)];
    const noun = NOUNS[Math.floor(Math.random() * NOUNS.length)];
    return `${adj}-${noun}`;
}
export function getLocalProjectsFromState(appState) {
    const result = [];
    for (const item of appState.projects.items) {
        if (item.data) {
            result.push({ slug: item.data.slug, path: item.data.path });
        }
    }
    return result;
}
